import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Temperatura } from './solution.mjs';

test('getter converte celsius para fahrenheit', () => {
  assert.equal(new Temperatura(0).fahrenheit, 32);
  assert.equal(new Temperatura(100).fahrenheit, 212);
});

test('setter converte fahrenheit para celsius', () => {
  const temperatura = new Temperatura(0);
  temperatura.fahrenheit = 212;
  assert.equal(temperatura.celsius, 100);
});

test('setter valida o valor recebido', () => {
  const temperatura = new Temperatura(0);
  assert.throws(() => {
    temperatura.fahrenheit = 'quente';
  });
});

test('setter atualiza e o getter reflete a mudança', () => {
  const temperatura = new Temperatura(0);
  temperatura.fahrenheit = 32;
  assert.equal(temperatura.celsius, 0);
  assert.equal(temperatura.fahrenheit, 32);
});

