// Temperatura guarda UM valor (celsius) e oferece fahrenheit calculado.
export class Temperatura {
  constructor(celsius) {
    this.celsius = celsius;
  }

  // Getter: ler .fahrenheit roda esta função — sem parênteses.
  get fahrenheit() {
    return (this.celsius * 9) / 5 + 32;
  }

  // Setter: escrever .fahrenheit valida e converte de volta para celsius.
  set fahrenheit(valor) {
    if (typeof valor !== 'number') {
      throw new Error('fahrenheit precisa ser um número');
    }
    this.celsius = ((valor - 32) * 5) / 9;
  }
}
